<?php

/* @autogenerated */
declare(strict_types=1);

namespace Tests\integration\Features\OAuth;

use PDO;
use Nimbly\Capsule\Factory\ServerRequestFactory;
use Nimbly\Capsule\Response;
use PHPUnit\Framework\TestCase;
use Psr\EventDispatcher\EventDispatcherInterface;
use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Infrastructure\Connector\Pdo\DcrInitialAccessTokenPdoConnector;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Infrastructure\Driven\DcrInitialAccessTokenCommandRepositoryAdapter;
use Civi\Lughauth\Features\Access\Tenant\Infrastructure\Connector\Pdo\TenantPdoConnector;
use Civi\Lughauth\Features\Access\Tenant\Infrastructure\Driven\TenantQueryRepositoryAdapter;
use Civi\Lughauth\Features\Access\TenantConfig\Infrastructure\Connector\Pdo\TenantConfigPdoConnector;
use Civi\Lughauth\Features\Access\TenantConfig\Infrastructure\Driven\TenantConfigQueryRepositoryAdapter;
use Civi\Lughauth\Features\Access\TrustedClient\Infrastructure\Connector\Pdo\TrustedClientPdoConnector;
use Civi\Lughauth\Features\Access\TrustedClient\Infrastructure\Driven\TrustedClientCommandRepositoryAdapter;
use Civi\Lughauth\Features\Access\TrustedClient\Infrastructure\Driven\TrustedClientQueryRepositoryAdapter;
use Civi\Lughauth\Features\OAuth\Client\Application\Usecase\DeleteDynamicClient\DeleteDynamicClientUsecase;
use Civi\Lughauth\Features\OAuth\Client\Application\Usecase\IssueInitialAccessToken\IssueInitialAccessTokenUsecase;
use Civi\Lughauth\Features\OAuth\Client\Application\Usecase\ReadDynamicClient\ReadDynamicClientUsecase;
use Civi\Lughauth\Features\OAuth\Client\Application\Usecase\RegisterClient\RegisterClientUsecase;
use Civi\Lughauth\Features\OAuth\Client\Application\Usecase\UpdateDynamicClient\UpdateDynamicClientUsecase;
use Civi\Lughauth\Features\OAuth\Client\Infrastructure\Driven\ClientStoreAdapter;
use Civi\Lughauth\Features\OAuth\Client\Infrastructure\Driven\DcrInitialAccessTokenSqlAdapter;
use Civi\Lughauth\Features\OAuth\Client\Infrastructure\Driven\DynamicClientAdapter;
use Civi\Lughauth\Features\OAuth\Client\Infrastructure\Driven\TrustedClientFinder;
use Civi\Lughauth\Features\OAuth\Client\Infrastructure\Driver\Rest\DynamicClientController;
use Civi\Lughauth\Features\OAuth\Client\Infrastructure\Driver\Rest\InitialAccessTokenIssueController;
use Civi\Lughauth\Shared\AppConfig;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Infrastructure\EntityChangelog\EntityChangelogService;
use Civi\Lughauth\Shared\Infrastructure\Sql\SqlTemplate;
use Civi\Lughauth\Shared\Security\Identity;
use Civi\Lughauth\Shared\Security\SecretDigester;
use Psr\Log\NullLogger;

/**
 * EP-03 end to end over MySQL and the real controllers: a tenant admin issues an initial access
 * token, a client registers with it through DCR and is managed only from its tenant.
 */
final class DcrRegistrationFlowTest extends TestCase
{
    private PDO $pdo;
    /** @var array<string, string> tenant uid by name */
    private array $tenants = [];
    private Identity $identity;
    private InitialAccessTokenIssueController $issue;
    private DynamicClientController $dcr;
    private ClientStoreAdapter $clients;

    protected function setUp(): void
    {
        $this->pdo = $this->connect();
        $suffix = bin2hex(random_bytes(4));
        foreach (['a', 'b'] as $key) {
            $this->tenants[$key] = $this->createTenant("dcr-flow-{$key}-{$suffix}");
        }
        $this->identity = $this->admin($this->tenants['a']);

        $sql = new SqlTemplate($this->pdo);
        $dispatcher = new class () implements EventDispatcherInterface {
            public function dispatch(object $event): object
            {
                return $event;
            }
        };
        $changelog = $this->createStub(EntityChangelogService::class);
        $tenantRepository = new TenantQueryRepositoryAdapter(new TenantPdoConnector($sql));
        $clientConnector = new TrustedClientPdoConnector($sql);
        $finder = new TrustedClientFinder(new TrustedClientQueryRepositoryAdapter($clientConnector), $tenantRepository);
        $digester = new SecretDigester(['p1' => 'pepper-one'], 'p1');
        $context = $this->createStub(Context::class);
        $context->method('getIdentity')->willReturnCallback(fn (): Identity => $this->identity);
        $context->method('getIssuer')->willReturnCallback(static fn (string $tenant): string => 'https://auth.example.com/oauth/openid/' . $tenant);

        $initialAccessTokens = new DcrInitialAccessTokenSqlAdapter(
            $this->pdo,
            $digester,
            $finder,
            $tenantRepository,
            new DcrInitialAccessTokenCommandRepositoryAdapter(new DcrInitialAccessTokenPdoConnector($sql), $dispatcher, $changelog),
        );
        $dynamicClients = new DynamicClientAdapter(
            new TrustedClientCommandRepositoryAdapter($clientConnector, $dispatcher, $changelog),
            $finder,
            new TenantConfigQueryRepositoryAdapter(new TenantConfigPdoConnector($sql)),
            $digester,
        );
        $this->issue = new InitialAccessTokenIssueController($context, $sql, new IssueInitialAccessTokenUsecase($initialAccessTokens));
        $this->dcr = new DynamicClientController(
            $context,
            new RegisterClientUsecase($dynamicClients, $initialAccessTokens),
            new ReadDynamicClientUsecase($dynamicClients),
            new UpdateDynamicClientUsecase($dynamicClients),
            new DeleteDynamicClientUsecase($dynamicClients),
        );
        $this->clients = new ClientStoreAdapter($digester, $finder);
        $this->clients->setLogger(new NullLogger());
    }

    protected function tearDown(): void
    {
        foreach ($this->tenants as $uid) {
            $params = ['tenant' => $uid];
            $this->pdo->prepare('DELETE r FROM access_trusted_client_allowed_redirect r JOIN access_trusted_client c ON c.uid = r.client WHERE c.tenant = :tenant')->execute($params);
            foreach (['access_trusted_client', 'access_dcr_initial_access_token', 'access_tenant_config'] as $table) {
                $this->pdo->prepare("DELETE FROM {$table} WHERE tenant = :tenant")->execute($params);
            }
            $this->pdo->prepare('DELETE FROM access_tenant WHERE uid = :tenant')->execute($params);
        }
    }

    public function testTenantAdminIssuesTokenAndTheRegisteredClientIsManagedOnlyFromItsTenant(): void
    {
        $issued = $this->issueToken([]);
        $this->assertSame(201, $issued->getStatusCode());
        $issuedBody = $this->json($issued);
        $token = $issuedBody['token'];
        $this->assertSame($this->tenants['a'], $this->column('SELECT tenant FROM access_dcr_initial_access_token WHERE uid = :uid', $issuedBody['uid']));

        $registered = $this->register('a', $token);
        $this->assertSame(201, $registered->getStatusCode());
        $client = $this->json($registered);
        $this->assertSame($this->tenants['a'], $this->column('SELECT tenant FROM access_trusted_client WHERE uid = :uid', $client['client_id']));
        $this->assertSame('invalid_token', $this->json($this->register('a', $token))['error'], 'max_uses = 1');

        $this->assertNotNull($this->clients->findEnabledClient($this->tenantName('a'), $client['client_id']));
        $this->assertNull($this->clients->findEnabledClient($this->tenantName('b'), $client['client_id']));

        $bearer = $client['registration_access_token'];
        $this->assertSame(401, $this->manage('GET', 'b', $client['client_id'], $bearer)->getStatusCode());
        $this->assertSame(200, $this->manage('GET', 'a', $client['client_id'], $bearer)->getStatusCode());
        $updated = $this->manage('PUT', 'a', $client['client_id'], $bearer, ['redirect_uris' => ['https://app.example.com/new'], 'client_name' => 'Renamed']);
        $this->assertSame('Renamed', $this->json($updated)['client_name']);
        $this->assertSame(401, $this->manage('DELETE', 'b', $client['client_id'], $bearer)->getStatusCode());
        $this->assertSame(204, $this->manage('DELETE', 'a', $client['client_id'], $bearer)->getStatusCode());
    }

    public function testTenantAdminCannotIssueForAnotherTenant(): void
    {
        $this->expectException(UnauthorizedException::class);

        $this->issueToken(['tenant' => ['$ref' => $this->tenants['b']]]);
    }

    public function testNonAdminCannotIssue(): void
    {
        $this->identity = $this->identity('user', $this->tenants['a'], []);

        $this->expectException(UnauthorizedException::class);

        $this->issueToken([]);
    }

    public function testRootMustNameTheTenantAndItsTokenOnlyRegistersThere(): void
    {
        $this->identity = $this->identity('root', $this->tenants['a'], ['admin'], 'platform:global_access');

        $this->assertSame(400, $this->issueToken([])->getStatusCode());
        $this->assertSame(400, $this->issueToken(['tenant' => ['$ref' => 'no-such-tenant']])->getStatusCode());

        $issued = $this->issueToken(['tenant' => ['$ref' => $this->tenants['b']]]);
        $this->assertSame(201, $issued->getStatusCode());
        $token = $this->json($issued)['token'];
        $this->assertSame('invalid_token', $this->json($this->register('a', $token))['error']);
        $this->assertSame(201, $this->register('b', $token)->getStatusCode());
    }

    private function issueToken(array $body): ResponseInterface
    {
        return $this->issue->issue($this->request('POST', '/api/access/dcr-initial-access-tokens/~/issue', $body), new Response(200), []);
    }

    private function register(string $tenant, string $token): ResponseInterface
    {
        $request = $this->request('POST', '/register', ['redirect_uris' => ['https://app.example.com/cb'], 'grant_types' => ['authorization_code', 'refresh_token']])
            ->withHeader('Authorization', 'Bearer ' . $token);
        return $this->dcr->post($request, new Response(200), ['tenant' => $this->tenantName($tenant)]);
    }

    private function manage(string $method, string $tenant, string $clientId, string $bearer, array $body = []): ResponseInterface
    {
        $request = $this->request($method, '/register/' . $clientId, $body)->withHeader('Authorization', 'Bearer ' . $bearer);
        $args = ['tenant' => $this->tenantName($tenant), 'client_id' => $clientId];
        return match ($method) {
            'GET' => $this->dcr->get($request, new Response(200), $args),
            'PUT' => $this->dcr->put($request, new Response(200), $args),
            'DELETE' => $this->dcr->delete($request, new Response(200), $args),
        };
    }

    private function request(string $method, string $uri, array $body): ServerRequestInterface
    {
        return (new ServerRequestFactory())->createServerRequest($method, $uri)->withParsedBody($body);
    }

    private function json(ResponseInterface $response): array
    {
        return json_decode((string) $response->getBody(), true) ?? [];
    }

    private function tenantName(string $key): string
    {
        return (string) $this->column('SELECT name FROM access_tenant WHERE uid = :uid', $this->tenants[$key]);
    }

    private function column(string $query, string $uid): mixed
    {
        $stmt = $this->pdo->prepare($query);
        $stmt->execute(['uid' => $uid]);
        return $stmt->fetchColumn();
    }

    private function admin(string $tenantUid): Identity
    {
        return $this->identity('tenant-admin', $tenantUid, ['admin']);
    }

    private function identity(string $id, string $tenantUid, array $roles, string $scope = ''): Identity
    {
        return new Identity(false, 'user', $id, $id, 'token', 'https://auth.example.com', $tenantUid, $roles, [], [], $scope, $id . '@example.com');
    }

    private function createTenant(string $name): string
    {
        $uid = 'tenant-' . $name;
        $this->pdo->prepare('INSERT INTO access_tenant (uid, version, domain, enabled, mark_for_delete, name, root) VALUES (:uid, 0, :domain, 1, 0, :name, 0)')
            ->execute(['uid' => $uid, 'domain' => $name . '.example.com', 'name' => $name]);
        $this->pdo->prepare(
            'INSERT INTO access_tenant_config (uid, version, tenant, dynamic_registration_policy, allow_password_grant, force_mfa,'
            . ' invitation_expiry_days, magic_link_expiry_minutes, refresh_token_max_lifetime_seconds, refresh_token_ttl_seconds,'
            . ' require_email_verification, require_pushed_authorization_requests, session_sso_ttl_seconds)'
            . " VALUES (:uid, 0, :tenant, 'token-required', 0, 0, 7, 15, 2592000, 36000, 0, 0, 3600)"
        )->execute(['uid' => 'config-' . $name, 'tenant' => $uid]);
        return $uid;
    }

    private function connect(): PDO
    {
        $config = new AppConfig();
        $dsn = $config->get('database.url');
        if (!is_string($dsn) || !str_starts_with($dsn, 'mysql:')) {
            $this->markTestSkipped('MySQL integration database not configured');
        }
        try {
            return new PDO($dsn, $config->get('database.username'), $config->get('database.password'), [
                PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
            ]);
        } catch (\PDOException) {
            $this->markTestSkipped('MySQL integration database not available');
        }
    }
}
